    ymm=min(yy for yy,_ in cl_); xmm=min(xx for _,xx in cl_)
    return tuple(sorted((yy-ymm,xx-xmm) for yy,xx in cl_))
tt=G['Test input']
cnt={v:sum(r.count(v) for r in tt) for v in set(v for r in tt for v in r)}
bgo=max(cnt,key=cnt.get)
cc=comps(tt,bgo,True)
sh=Counter(norm(c_) for col,c_ in cc)
mx=max(sh.values())
best=None
for col,c_ in cc:
    s=norm(c_)
    if sh[s]==mx and (best is None or len(c_)>len(best)):
        best=c_
yem=max(yy for yy,_ in best); xem=max(xx for _,xx in best)
res=[tt[i][min(xx for _,xx in best):xem+1] for i in range(min(yy for yy,_ in best),yem+1)]
print(json.dumps(res))
